# Generated by Claude Opus 5.5 (claude.ai/code) · 2026-11-18
# Pester tests: host-config-linux recipe.

BeforeAll {
    . (Join-Path $PSScriptRoot '../TestHelpers.ps1')
}

AfterAll {
    Remove-TestWork
}

Describe 'host-config-linux recipe' -Skip:(-not $IsLinux) {
    BeforeAll {
        # a fake host root: config to keep, secrets that must never be archived
        $script:hr = Join-Path $Work 'hcl-root'
        $files = [ordered]@{
            'etc/fstab'                               = 'UUID=x / ext4'
            'etc/app/app.conf'                        = 'keep'
            'etc/app/inline-secret.conf'              = 'password=x'
            'etc/shadow'                              = 'SECRET'
            'etc/shadow-'                             = 'SECRET'
            'etc/ssh/ssh_host_ed25519_key'            = 'SECRET'
            'etc/ssh/ssh_host_ed25519_key.pub'        = 'pub'
            'etc/ssl/private/site.pem'                = 'SECRET'
            'etc/ssl/certs/ca.pem'                    = 'public'
            'etc/backup-sequencer/secrets/smtp.pass'  = 'SECRET'
            'etc/backup-sequencer/config.json'        = '{}'
            'etc/myapp/tls/server.key'                = 'SECRET'
            'opt/restic.pass'                         = 'SECRET'
            'root/.bashrc'                            = 'keep'
            'root/.bash_history'                      = 'SECRET'
            'root/.ssh/id_ed25519'                    = 'SECRET'
            'root/.ssh/id_ed25519.pub'                = 'pub'
            'root/.ssh/authorized_keys'               = 'pub'
            'root/.docker/config.json'                = 'SECRET'
            'root/.cache/blob'                        = 'cache'
            'root/notes.bak'                          = 'excluded by pattern'
            'var/spool/cron/crontabs/root'            = '0 1 * * * true'
            'usr/local/bin/tool'                      = 'BINARY'
            'usr/local/etc/tool.conf'                 = 'keep'
            'srv/scripts/job.sh'                      = 'keep'
        }
        foreach ($k in $files.Keys) {
            $p = Join-Path $hr $k
            New-Item -ItemType Directory -Force -Path (Split-Path -Parent $p) | Out-Null
            Set-Content -LiteralPath $p -Value $files[$k]
        }

        # fact stubs: one ok, one failing, one hanging (a missing one is just a bad name)
        $script:stubDir = Join-Path $Work 'hcl-stubs'
        New-Item -ItemType Directory -Force -Path $stubDir | Out-Null
        $stubs = @{ 'ok.sh' = "#!/bin/sh`necho hello fact"; 'fail.sh' = "#!/bin/sh`necho partial`necho boom >&2`nexit 3"; 'slow.sh' = "#!/bin/sh`nsleep 20" }
        foreach ($k in $stubs.Keys) {
            $p = Join-Path $stubDir $k
            Set-Content -LiteralPath $p -NoNewline -Value $stubs[$k]
            & chmod '+x' $p
        }

        $script:newHcl = {
            param($envHash, $outName)
            $rc = & (Get-Module BackupCommon) { [RecipeContext]::new() }   # class lives in the module scope
            $rc.Service = 'host'
            $rc.OutDir = Join-Path $Work $outName
            $rc.Env = [pscustomobject]$envHash
            $rc.ConfiguredSteps = @('dump')
            & (Join-Path $TestsDir '../src/recipes/host-config-linux.ps1') -Recipe $rc | Out-Null
            $rc
        }
    }

    It 'archives host config relative to the root and leaves every secret out' {
        Set-StrictMode -Version Latest   # as the engine runs steps
        $rc = & $newHcl @{ HCL_ROOT = $hr; HCL_EXTRA_DIRS = '/srv/scripts'; HCL_EXCLUDES = '/etc/app/inline-secret.conf;*.bak'; RESTIC_PASSWORD_FILE = '/opt/restic.pass' } 'hcl-out1'
        $rc.State['HclFacts'] = @()
        & $rc.Steps['dump'] $rc
        $list = @(& tar -tf (Join-Path $rc.OutDir 'host_files.tar'))
        $l = $list -join "`n"

        foreach ($keep in 'etc/fstab', 'etc/app/app.conf', 'etc/ssh/ssh_host_ed25519_key.pub', 'etc/ssl/certs/ca.pem',
            'etc/backup-sequencer/config.json', 'root/.bashrc', 'root/.ssh/id_ed25519.pub', 'root/.ssh/authorized_keys',
            'var/spool/cron/crontabs/root', 'usr/local/etc/tool.conf', 'srv/scripts/job.sh') {
            $list | Should -Contain $keep
        }
        $l | Should -Not -Match 'shadow'
        $l | Should -Not -Match 'ssh_host_ed25519_key$'
        $l | Should -Not -Match '(?m)^etc/ssl/private/.'
        $l | Should -Not -Match 'backup-sequencer/secrets/.'
        $l | Should -Not -Match 'server\.key'
        $l | Should -Not -Match '(?m)^root/\.ssh/id_ed25519$'
        $l | Should -Not -Match 'bash_history'
        $l | Should -Not -Match '\.docker/config\.json'
        $l | Should -Not -Match '(?m)^root/\.cache/.'
        $l | Should -Not -Match 'inline-secret|notes\.bak'   # HCL_EXCLUDES: absolute + pattern
        $l | Should -Not -Match 'usr/local/bin'              # tools are listed in facts, not archived
        $l | Should -Not -Match '^/'                         # paths relative to the root
    }

    It 'writes facts: output kept, missing skipped, failures and timeouts recorded with one warning' {
        Set-StrictMode -Version Latest   # as the engine runs steps
        $rc = & $newHcl @{ HCL_ROOT = $hr } 'hcl-out2'
        $rc.State['HclFactTimeoutSec'] = 1
        $listing = @($rc.State['HclFacts'] | Where-Object { $_.Name -eq 'usr-local' })
        $rc.State['HclFacts'] = @(
            @{ Name = 'ok'; Exe = (Join-Path $stubDir 'ok.sh'); Args = @() }
            @{ Name = 'gone'; Exe = 'no-such-command-hcl'; Args = @() }
            @{ Name = 'fail'; Exe = (Join-Path $stubDir 'fail.sh'); Args = @() }
            @{ Name = 'slow'; Exe = (Join-Path $stubDir 'slow.sh'); Args = @() }
        ) + $listing
        $t = [System.Diagnostics.Stopwatch]::StartNew()
        $warn = @(& $rc.Steps['dump'] $rc 3>&1 | Where-Object { $_ -is [System.Management.Automation.WarningRecord] })
        $t.Elapsed.TotalSeconds | Should -BeLessThan 10   # the hanging command was killed

        $fd = Join-Path $rc.OutDir 'facts'
        (Get-Content -LiteralPath (Join-Path $fd 'ok.txt') -Raw) | Should -Match 'hello fact'
        (Test-Path -LiteralPath (Join-Path $fd 'gone.txt')) | Should -BeFalse
        (Get-Content -LiteralPath (Join-Path $fd '_skipped.txt') -Raw) | Should -Match 'gone: no-such-command-hcl not installed'
        $fail = Get-Content -LiteralPath (Join-Path $fd 'fail.txt') -Raw
        $fail | Should -Match 'partial'
        $fail | Should -Match 'exit 3'
        $fail | Should -Match 'boom'
        (Get-Content -LiteralPath (Join-Path $fd 'slow.txt') -Raw) | Should -Match 'timed out after 1s'
        @(Get-ChildItem -LiteralPath $fd -Filter '*.stderr').Count | Should -Be 0
        $u = Get-Content -LiteralPath (Join-Path $fd 'usr-local.txt') -Raw
        $u | Should -Match 'file  7  \S+  [0-9a-f]{64}  /usr/local/bin/tool'
        $warn.Count | Should -Be 1
        "$($warn[0].Message)" | Should -Match '2 command\(s\) failed: fail, slow'
    }

    It 'validate flags a missing extra dir and a missing root' {
        Set-StrictMode -Version Latest   # as the engine runs steps
        $rc = & $newHcl @{ HCL_ROOT = $hr; HCL_EXTRA_DIRS = '/srv/scripts;/srv/nope' } 'hcl-out3'
        $p = @(& $rc.ValidateBlock $rc)
        $p -join "`n" | Should -Match 'HCL_EXTRA_DIRS entry missing: /srv/nope'
        $p.Count | Should -Be 1
        $rc = & $newHcl @{ HCL_ROOT = (Join-Path $Work 'hcl-no-root') } 'hcl-out4'
        (& $rc.ValidateBlock $rc) -join "`n" | Should -Match 'HCL_ROOT missing'
    }

    It 'publishes the files tar and the facts dir through a real run' {
        $n = [guid]::NewGuid().ToString('n').Substring(0, 8)
        $root = Join-Path $Work "hcl-lc-$n"
        $paths = @{ BaseDir = $TestsDir; EventsPath = (Join-Path $Work "hcl-lc-$n.jsonl"); LockPath = ($root + '.lock'); SpoolRoot = $root }
        $cfg = (@'
{ "window": { "open": "00:00", "close": "23:59" },
  "services": { "host": { "enabled": true, "script": "../src/recipes/host-config-linux.ps1",
    "env": { "HCL_ROOT": "__ROOT__" },
    "steps": [ { "name": "dump", "resources": [] } ] } } }
'@ -replace '__ROOT__', ($hr -replace '\\', '/')) | ConvertFrom-Json
        Invoke-BackupRun -Config $cfg -Paths $paths -ForceWindow -WarningAction SilentlyContinue | Out-Null
        $set = Join-Path $root 'ready/host'
        (Test-Path -LiteralPath (Join-Path $set 'host_files.tar')) | Should -BeTrue
        (Test-Path -LiteralPath (Join-Path $set 'facts/usr-local.txt')) | Should -BeTrue
    }
}
